<script type="application/ld+json">{"@context": "https://schema.org", "@type": "FAQPage", "inLanguage": "en", "mainEntity": [{"@type": "Question", "name": "Is Google Business Profile paid?", "acceptedAnswer": {"@type": "Answer", "text": "No. Creating, verifying and managing a Google Business Profile is free. Google also states that local ranking can’t be improved by paying; ads in map results are a separate paid service and are labelled as ads."}}, {"@type": "Question", "name": "Can I register on Google Maps without an address?", "acceptedAnswer": {"@type": "Answer", "text": "Yes. If you provide services by going to customers’ addresses, you can register as a service-area business, hide your address and specify the districts and cities you serve. Virtual offices and PO box addresses, however, aren’t considered suitable for a profile."}}, {"@type": "Question", "name": "Do Google reviews affect ranking?", "acceptedAnswer": {"@type": "Answer", "text": "Yes. According to Google’s help page, more reviews and positive ratings can contribute to a business’s prominence signal. Replying to reviews is also recommended. However, offering discounts or gifts in exchange for reviews and collecting fake reviews violate the guidelines."}}, {"@type": "Question", "name": "Why does my competitor rank above me on maps?", "acceptedAnswer": {"@type": "Answer", "text": "It’s usually one of three reasons: the competitor is closer to the searcher, their profile is more complete and their category more accurate, or they have more and more recent reviews. You can’t change distance, but you can strengthen your profile information, your flow of reviews and your website."}}, {"@type": "Question", "name": "How long does Google Business Profile verification take?", "acceptedAnswer": {"@type": "Answer", "text": "The verification method varies by business; most often a short video showing the business is requested, and the review can take a few days. Avoiding frequent changes to your information during the review prevents the process from dragging on."}}]}</script>
